def _config_pairs(pairs):
    """json object_pairs_hook：保序构造 dict，重复键抛 ConfigError。"""
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise ConfigError("duplicate key")
        obj[key] = value
    return obj


